// ============================================================
// schools.js — the two schools that share this portal
//   primary → Criterion Amazing Nursery and Primary School (Creche 1 – Primary 5)
//   college → Criterion Amazing College Osogbo              (J.S.S 1 – S.S 3)
// Which school a student belongs to is decided by their CLASS, so when a
// Primary 5 pupil is promoted to J.S.S 1 they move to the College portal
// automatically. Must be loaded after data.js and logo.js.
// ============================================================

const SCHOOLS = {
  primary: {
    key: 'primary',
    name: 'Criterion Amazing Nursery and Primary School',
    short: 'Nursery & Primary',
    range: 'Creche 1 – Primary 5',
    headerLines: ['CRITERION AMAZING', 'NURSERY AND PRIMARY SCHOOL'],
    commentName: 'Criterion Amazing Nursery and Primary School',
    motto: 'Nurturing Globally Competitive Students',
    path: '/primary',
    logo: 'data:image/png;base64,'
  },
  college: {
    key: 'college',
    name: 'Criterion Amazing College Osogbo',
    short: 'College Osogbo',
    range: 'J.S.S 1 – S.S 3',
    headerLines: ['CRITERION AMAZING COLLEGE, OSOGBO'],
    commentName: 'Criterion Amazing College',
    motto: 'Training Globally Competitive Students',
    path: '/college',
    logo: 'data:image/png;base64,'
  }
};

// Same rule the server uses (server.js → schoolKeyOfClass).
function schoolKeyOfClass(classId) {
  return /^(J\.S\.S|S\.S)/i.test(String(classId || '').trim()) ? 'college' : 'primary';
}
function schoolOfClass(classId) { return SCHOOLS[schoolKeyOfClass(classId)]; }

// The school portal the signed-in user came through ('' for the admin portal).
function currentSchoolKey() { return sessionStorage.getItem('cc_school') || ''; }
function currentSchool() { return SCHOOLS[currentSchoolKey()] || null; }

// Classes the current portal is allowed to show. Admin portal → every class.
function visibleClasses() {
  const key = currentSchoolKey();
  return key ? ALL_CLASSES.filter(c => schoolKeyOfClass(c) === key) : ALL_CLASSES.slice();
}

// School name as it appears at the top of report cards / receipts / letters.
// Long names are split over two lines and set slightly smaller so they fit.
function schoolHeaderHTML(school, basePx, extraStyle) {
  const lines = school.headerLines;
  const px = lines.length > 1 ? Math.round(basePx * 0.8) : basePx;
  return `<div style="font-size:${px}px;font-weight:900;color:#55A845;text-transform:uppercase;letter-spacing:1px;line-height:1.1;${extraStyle || ''}">${lines.join('<br/>')}</div>`;
}
